function bwEsc(v) {
    return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
}
function bwSafeUrl(u) {
    return /^https?:\/\//i.test(u || '') ? u : null;
}
function bwFoodPopup(p) {
    var kind = p.cuisine && p.cuisine.length ? p.cuisine.join(', ') : String(p.kind).replace('shop:', '').replace(/_/g, ' ');
    var h = '<h6>' + bwEsc(p.name) + '</h6><div class="small text-capitalize">' + bwEsc(kind) + '</div>';
    var rows = [];
    if (p.address) rows.push('<i class="fas fa-map-marker-alt"></i> ' + bwEsc(p.address));
    if (p.opening_hours) rows.push('<i class="far fa-clock"></i> ' + bwEsc(p.opening_hours));
    if (p.phone) rows.push('<i class="fas fa-phone"></i> <a href="tel:' + bwEsc(p.phone.replace(/[^+\d]/g, '')) + '">' + bwEsc(p.phone) + '</a>');
    var site = bwSafeUrl(p.website);
    if (site) rows.push('<i class="fas fa-globe"></i> <a href="' + bwEsc(site) + '" target="_blank" rel="noopener noreferrer nofollow">Website</a>');
    var tags = [];
    if (p.vegetarian === 'only') tags.push('Pure vegetarian'); else if (p.vegetarian) tags.push('Vegetarian options');
    if (p.vegan) tags.push('Vegan options');
    if (p.halal) tags.push('Halal');
    if (p.takeaway) tags.push('Takeaway');
    if (p.delivery) tags.push('Delivery');
    if (p.outdoor_seating) tags.push('Outdoor seating');
    if (p.wifi) tags.push('WiFi');
    if (tags.length) rows.push(bwEsc(tags.join(' · ')));
    if (p.from_stay_road_km != null) rows.push('<i class="fas fa-route"></i> ' + p.from_stay_road_km + ' km by road from Black &amp; White Stays');
    h += '<div class="small">' + rows.join('<br>') + '</div>';
    h += '<div class="small mt-1"><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.google.com/maps/dir/?api=1&destination=' +
        encodeURIComponent(p.lat + ',' + p.lon) + '">Directions</a>';
    if (p.osm_edit_url) h += ' · <a target="_blank" rel="noopener noreferrer nofollow" href="' + bwEsc(p.osm_edit_url) + '">Add missing details on OpenStreetMap</a>';
    h += ' &middot; <a target="_blank" rel="noopener noreferrer nofollow" href="https://github.com/bwstays/bwstays/issues/new?labels=data&title=' +
        encodeURIComponent('Food map correction: ' + p.name) + '">Report a correction</a>';
    h += '</div>';
    if (p.unverified_position) h += '<div class="small text-muted">Position from the site\'s own list; not yet confirmed on OpenStreetMap.</div>';
    return h;
}
// Food map: the same pill filters as the all-locations map, by type of place.
var BW_FOOD_CATEGORIES = [
    { key: 'restaurant', label: 'Restaurants', kinds: ['restaurant', 'food_court'] },
    { key: 'cafe', label: 'Cafes', kinds: ['cafe'] },
    { key: 'bakery', label: 'Bakeries & sweets', kinds: ['shop:bakery', 'shop:confectionery', 'shop:sweets', 'shop:pastry', 'shop:deli', 'ice_cream'] },
    { key: 'fast_food', label: 'Fast food', kinds: ['fast_food'] },
    { key: 'bar', label: 'Bars & pubs', kinds: ['bar', 'pub', 'biergarten'] }
];
function bwRenderFoodMap(d) {
    var cats = BW_FOOD_CATEGORIES.map(function (c) { return { key: c.key, label: c.label, kinds: c.kinds, count: 0, group: L.featureGroup(), on: true }; });
    var other = { key: 'other', label: 'Other', kinds: [], count: 0, group: L.featureGroup(), on: true };
    d.places.forEach(function (p) {
        var c = cats.filter(function (x) { return x.kinds.indexOf(p.kind) !== -1; })[0] || other;
        c.count++;
        L.marker([p.lat, p.lon], { title: p.name, icon: myIcon1 }).bindPopup(bwFoodPopup(p), { maxWidth: 280 }).addTo(c.group);
    });
    cats.push(other);
    cats = cats.filter(function (c) { return c.count > 0; });

    var bar = document.createElement('div');
    bar.className = 'bw-map-filters';
    bar.setAttribute('role', 'group');
    bar.setAttribute('aria-label', 'Filter food places on the map');
    var allBtn;
    function paint() {
        var all = cats.every(function (c) { return c.on; });
        allBtn.className = 'bw-map-pill' + (all ? ' is-on' : '');
        allBtn.setAttribute('aria-pressed', all ? 'true' : 'false');
        cats.forEach(function (c) {
            c.btn.className = 'bw-map-pill' + (c.on ? ' is-on' : '');
            c.btn.setAttribute('aria-pressed', c.on ? 'true' : 'false');
            if (c.on) c.group.addTo(map1); else map1.removeLayer(c.group);
        });
    }
    allBtn = document.createElement('button');
    allBtn.type = 'button';
    allBtn.textContent = 'All (' + d.places.length + ')';
    allBtn.addEventListener('click', function () {
        var all = cats.every(function (c) { return c.on; });
        cats.forEach(function (c) { c.on = !all; });
        paint();
    });
    bar.appendChild(allBtn);
    cats.forEach(function (c) {
        c.btn = document.createElement('button');
        c.btn.type = 'button';
        c.btn.textContent = c.label + ' (' + c.count + ')';
        c.btn.addEventListener('click', function () { c.on = !c.on; paint(); });
        bar.appendChild(c.btn);
    });
    element1.parentNode.insertBefore(bar, element1);
    paint();
}

function bwAddLegacyMarkers() {
    var i;
    for (i = 0; i < loc.length; i++) {
        var target = L.latLng(loc[i][1], loc[i][2]);
        L.marker(target, { title: loc[i][5], icon: myIcon1 }).on('tileload', function (e) {
            e.tile.alt = 'All Locations at wayand';
        }).addTo(map1).bindPopup(loc[i][0]);
    }
}
if (typeof mapType !== 'undefined' && mapType == 1) {
    // Static dataset built by scripts/build-food.mjs (OpenStreetMap, ODbL): no third-party API call at view time.
    fetch(iconURLPrefix + 'data/food-places.json')
        .then(function (r) { return r.json(); })
        .then(function (d) {
            bwRenderFoodMap(d);
            map1.setView([11.6057872, 76.0833109], 12);
        })
        .catch(function () {
            bwAddLegacyMarkers();
        });
} else if (typeof mapType !== 'undefined' && mapType == 2) {
    // All-locations map: category filters over data/map-places.json (built by scripts/build-map-data.mjs)
    fetch(iconURLPrefix + 'data/map-places.json')
        .then(function (r) { return r.json(); })
        .then(bwRenderPlaceMap)
        .catch(function () {
            bwAddLegacyMarkers();
        });
} else {
    bwAddLegacyMarkers();
}

function bwPlacePopup(p) {
    var h = '';
    if (p.img) {
        h += '<img src="' + bwEsc(p.img) + '" alt="' + bwEsc(p.name) + '" width="240" style="max-width:100%;height:auto">';
    }
    var title = bwEsc(p.name);
    var link = bwSafeUrl(p.url);
    h += '<h6 class="mt-1">' + (link ? '<a href="' + bwEsc(link) + '">' + title + '</a>' : title) + '</h6>';
    var meta = [p.label];
    if (p.district) meta.push(p.district);
    if (p.km != null) meta.push(p.km + ' km from Kalpetta');
    h += '<div class="small">' + bwEsc(meta.join(' · ')) + '</div>';
    if (p.note) h += '<div class="small text-muted">' + bwEsc(p.note) + '</div>';
    h += '<div class="small mt-1"><a target="_blank" rel="noopener noreferrer nofollow" href="https://www.google.com/maps/dir/?api=1&destination=' +
        encodeURIComponent(p.lat + ',' + p.lon) + '">Directions</a></div>';
    return h;
}

function bwRenderPlaceMap(data) {
    var groups = {};
    var shown = {};
    data.categories.forEach(function (c) {
        groups[c.key] = L.featureGroup();
        shown[c.key] = true;
    });
    data.places.forEach(function (p) {
        var g = groups[p.cat];
        if (g) {
            L.marker([p.lat, p.lon], { title: p.name, icon: myIcon1 }).bindPopup(bwPlacePopup(p), { maxWidth: 260 }).addTo(g);
        }
    });

    // filter bar, inserted above the map
    var bar = document.createElement('div');
    bar.className = 'bw-map-filters';
    bar.setAttribute('role', 'group');
    bar.setAttribute('aria-label', 'Filter places on the map');
    var buttons = {};
    function paint() {
        Object.keys(buttons).forEach(function (k) {
            var on = k === 'all' ? Object.keys(shown).every(function (x) { return shown[x]; }) : shown[k];
            buttons[k].className = 'bw-map-pill' + (on ? ' is-on' : '');
            buttons[k].setAttribute('aria-pressed', on ? 'true' : 'false');
        });
    }
    function apply() {
        data.categories.forEach(function (c) {
            if (shown[c.key]) groups[c.key].addTo(map1); else map1.removeLayer(groups[c.key]);
        });
        paint();
    }
    function add(key, label, onClick) {
        var b = document.createElement('button');
        b.type = 'button';
        b.textContent = label;
        b.addEventListener('click', onClick);
        buttons[key] = b;
        bar.appendChild(b);
    }
    add('all', 'All (' + data.places.length + ')', function () {
        var allOn = Object.keys(shown).every(function (x) { return shown[x]; });
        Object.keys(shown).forEach(function (x) { shown[x] = !allOn; });
        apply();
    });
    data.categories.forEach(function (c) {
        add(c.key, c.label + ' (' + c.count + ')', function () {
            shown[c.key] = !shown[c.key];
            apply();
        });
    });
    element1.parentNode.insertBefore(bar, element1);
    apply();
    map1.setView([data.center.lat, data.center.lon], 10);
}
